{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--accent:#2b6cb0;--accent-2:#f6ad55;--bg:#0f1724;--card:#0b1220;--muted:#9aa4b2;--glass:rgba(255,255,255,0.04)}
    html,body{height:100%;margin:0;font-family:system-ui,-apple-system,"Segoe UI",Roboto,'Helvetica Neue',Arial;color:#e6eef8;background:linear-gradient(180deg,var(--bg),#071023);}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 28px;background:linear-gradient(90deg,rgba(255,255,255,0.02),transparent);backdrop-filter:blur(4px)}
    .brand{display:flex;gap:14px;align-items:center}
    .logo{width:44px;height:44px;background:var(--glass);border-radius:10px;display:grid;place-items:center;font-weight:700;color:var(--accent-2)}
    nav a{color:#dbeeff;margin:0 10px;text-decoration:none;font-weight:600;font-size:14px}
    main{max-width:980px;margin:36px auto;padding:20px}
    .hero{display:grid;grid-template-columns:1fr;gap:18px;padding:28px;border-radius:12px;background:linear-gradient(180deg,rgba(255,255,255,0.02),rgba(255,255,255,0.01));box-shadow:0 6px 30px rgba(2,6,23,0.6)}
    .hero h1{margin:0;color:#fff;font-size:28px;letter-spacing:-0.02em}
    .hero p{margin:0;color:var(--muted);line-height:1.45}
    .cta-row{display:flex;gap:12px;margin-top:12px}
    .btn{background:var(--accent);color:white;padding:10px 14px;border-radius:8px;text-decoration:none;font-weight:700}
    .btn.secondary{background:transparent;border:1px solid rgba(255,255,255,0.06);color:#d5e7ff}
    .story{margin-top:20px;padding:20px;background:linear-gradient(180deg,rgba(255,255,255,0.01),transparent);border-radius:10px}
    .columns{display:grid;grid-template-columns:1fr 320px;gap:18px}
    .bio p{color:#d6e9ff}
    .framework{margin-top:18px;padding:18px;border-radius:10px;background:linear-gradient(90deg,rgba(255,255,255,0.01),rgba(255,255,255,0.01));color:#eaf5ff}
    .pill{display:inline-block;background:rgba(255,255,255,0.03);padding:6px 10px;border-radius:999px;margin-right:8px;font-size:13px}
    .proof{margin-top:18px;padding:18px;border-radius:10px;background:linear-gradient(90deg,rgba(255,255,255,0.01),transparent)}
    .testimonial{min-height:80px}
    .badges{display:flex;gap:10px;margin-top:12px}
    .badge{display:inline-flex;align-items:center;gap:8px;background:rgba(255,255,255,0.02);padding:8px;border-radius:8px;cursor:default}
    .tooltip{position:absolute;background:#0b1220;color:#dbeeff;padding:8px;border-radius:6px;border:1px solid rgba(255,255,255,0.03);font-size:13px;white-space:nowrap;transform:translateY(-8px);opacity:0;pointer-events:none;transition:opacity .18s}
    .conf{margin-top:18px;padding:18px;background:linear-gradient(180deg,rgba(255,255,255,0.01),transparent);border-radius:10px}
    .accordion{border-radius:8px;background:var(--card);padding:8px}
    .acc-head{display:flex;justify-content:space-between;align-items:center;padding:12px;cursor:pointer}
    .acc-body{padding:12px;border-top:1px dashed rgba(255,255,255,0.03);display:none;color:var(--muted)}
    footer{margin-top:26px;padding:22px;color:var(--muted);font-size:14px;text-align:center}
    /* responsive */
    @media(max-width:820px){.columns{grid-template-columns:1fr}.badge{font-size:13px}}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">{{BUSINESS_NAME}}</div>
      <div style="color:#e8f4ff;font-weight:700">Private Practice</div>
    </div>
    <nav aria-label="Main navigation">
      <a href="index.html">Start</a>
      <a href="about.html">Why work with me</a>
      <a href="specialties.html">Focus Areas</a>
      <a href="approach.html">Method</a>
      <a href="fees.html">Investment</a>
      <a href="faq.html">Q&amp;A</a>
      <a href="book.html">Schedule</a>
      <a href="contact.html">Reach</a>
    </nav>
  </header>
  <main>
    <section class="hero" aria-labelledby="hero-heading">
      <div>
        <h1 id="hero-heading">Practice with clarity, not pressure</h1>
        <p>I work with adults navigating transitions, overwhelm, and the routines that no longer fit. Sessions are practical, grounded and designed to help you find clear next steps.</p>
        <div class="cta-row">
          <a class="btn" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn secondary" href="contact.html">Contact — {{PHONE}}</a>
        </div>
      </div>
    </section>

    <section class="story">
      <div class="columns">
        <div class="bio">
          <h2 style="margin-top:0;color:#f3fbff">A bit about how I work</h2>
          <p>I’m a licensed clinician offering focused, evidence-informed care that prioritizes your safety and autonomy. My work favors clear structure: we name the immediate challenge, try a practical step, and review how it landed. Over time, those small course corrections add up to meaningful change.</p>

          <p>I aim to create a space free of judgment where you can consider options and choose what fits you now. I partner with people who want direct feedback, realistic plans, and steady support while they move through change.</p>
        </div>
        <aside style="padding:14px;background:var(--glass);border-radius:10px;color:#dbeeff">
          <strong>Connect:</strong>
          <p style="margin:8px 0 0 0">Phone: <a href="tel:{{PHONE}}" style="color:#fff;text-decoration:none">{{PHONE}}</a><br>Email: <a href="mailto:{{EMAIL}}" style="color:#fff;text-decoration:none">{{EMAIL}}</a></p>
          <div style="margin-top:12px"><span class="pill">VIP Day</span><span class="pill">Focused Packages</span></div>
        </aside>
      </div>
    </section>

    <section class="proof" aria-labelledby="proof-heading">
      <h3 id="proof-heading" style="margin:0 0 8px 0;color:#eaf5ff">Proof Gallery</h3>
      <div class="testimonial" id="testimonial">"I left each session with one clear, doable thing. Those things compounded into real momentum." — L.</div>
      <div style="display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:12px">
        <div class="badges" id="badges">
          <div class="badge" data-tooltip="Licensed in the state where I practice"> 
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" aria-hidden="true"><rect width="24" height="24" rx="5" fill="#2b6cb0"/></svg>
            <span>License</span>
          </div>
          <div class="badge" data-tooltip="Member of professional associations for continuing education">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" aria-hidden="true"><circle cx="12" cy="12" r="10" fill="#f6ad55"/></svg>
            <span>Memberships</span>
          </div>
          <div class="badge" data-tooltip="Client feedback gathered anonymously and voluntarily">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M4 12h16" stroke="#9ae6b4" stroke-width="2" stroke-linecap="round"/></svg>
            <span>Feedback</span>
          </div>
        </div>
        <div style="display:flex;gap:8px;align-items:center">
          <button class="btn secondary" id="prev">Prev</button>
          <button class="btn" id="next">Next</button>
        </div>
      </div>
    </section>

    <section class="framework">
      <h3 style="margin-top:0">How a few sessions can help</h3>
      <div style="display:flex;gap:12px;flex-wrap:wrap">
        <div style="flex:1;min-width:220px"> 
          <strong>Short clarity work</strong>
          <p style="margin:6px 0 0 0;color:var(--muted)">One to three sessions focused on a decision or immediate challenge—define options, test a step, and refine.</p>
        </div>
        <div style="flex:1;min-width:220px">
          <strong>VIP focus day</strong>
          <p style="margin:6px 0 0 0;color:var(--muted)">An intensive, single-day engagement for concentrated reflection and planning when time and clarity are scarce.</p>
        </div>
        <div style="flex:1;min-width:220px">
          <strong>Ongoing rhythm</strong>
          <p style="margin:6px 0 0 0;color:var(--muted)">Short-term or weekly sessions that keep you moving with consistent, measurable goals.</p>
        </div>
      </div>
    </section>

    <section class="conf" aria-labelledby="conf-label">
      <h3 id="conf-label">Session boundaries & confidentiality</h3>
      <div class="accordion" id="accordion">
        <div class="acc-head" role="button" tabindex="0" aria-expanded="false">Privacy basics <span aria-hidden="true">▾</span></div>
        <div class="acc-body">
          <p>Conversations are private and recorded only in clinical notes. There are legal limits to confidentiality, including situations that involve imminent harm to yourself or others, concerns about child or dependent safety, or court orders. We will review those limits during our first meeting.</p>
        </div>
        <div class="acc-head" role="button" tabindex="0" aria-expanded="false">Session policies <span aria-hidden="true">▾</span></div>
        <div class="acc-body">
          <p>Sessions are scheduled in advance; cancellations are requested with reasonable notice. I do not provide emergency services. If you are unable to keep an appointment, please contact me as soon as possible so we can reschedule.</p>
        </div>
      </div>

      <div style="margin-top:12px;padding:12px;background:linear-gradient(90deg,#0b1a2b,transparent);border-radius:8px;color:#ffdeda">
        <strong>Crisis resources</strong>
        <p style="margin:8px 0 0 0;color:#ffdede">If you are in immediate danger, call 911 or your local emergency number. If you are experiencing a mental health crisis and need support right now, consider contacting your local crisis hotline or dialing 988 (US) where available. If you are outside the United States, please contact your local emergency services or nearest crisis resource.</p>
      </div>
    </section>

    <section style="margin-top:18px;padding:18px;border-radius:10px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent)">
      <h3 style="margin-top:0">Ready to begin?</h3>
      <p style="color:var(--muted)">If you'd like to explore working together, we can start with a brief consultation to see if the fit feels right.</p>
      <div style="margin-top:10px">
        <a class="btn" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <a class="btn secondary" href="contact.html">Email: {{EMAIL}}</a>
      </div>
    </section>

  </main>
  <footer>
    <div>{{BUSINESS_NAME}} • {{CITY}}, {{STATE}} • <a href="tel:{{PHONE}}" style="color:inherit">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}" style="color:inherit">{{EMAIL}}</a></div>
  </footer>

  <div id="tooltip" class="tooltip" role="tooltip" aria-hidden="true"></div>

  <script>
    (function(){
      // Accordion
      const heads = document.querySelectorAll('.acc-head');
      heads.forEach(h=>{
        const toggle = ()=>{
          const next = h.nextElementSibling;
          const expanded = h.getAttribute('aria-expanded') === 'true';
          h.setAttribute('aria-expanded', !expanded);
          if(!expanded){ next.style.display='block'; } else { next.style.display='none'; }
        };
        h.addEventListener('click', toggle);
        h.addEventListener('keydown', function(e){ if(e.key==='Enter' || e.key===' ') { e.preventDefault(); toggle(); } });
      });

      // Proof gallery
      const items = [
        {text: '"I left each session with one clear, doable thing. Those things compounded into real momentum." — L.'},
        {text: '"Practical feedback and a calm frame made it easier to try new ways of being." — R.'},
        {text: '"The intensive day helped me map a path I could actually use the next week." — M.'}
      ];
      let idx = 0;
      const el = document.getElementById('testimonial');
      const prev = document.getElementById('prev');
      const next = document.getElementById('next');
      function show(i){ el.textContent = items[i].text; }
      function advance(n){ idx = (idx + n + items.length) % items.length; show(idx); }
      prev.addEventListener('click', ()=>{ advance(-1); resetAuto(); });
      next.addEventListener('click', ()=>{ advance(1); resetAuto(); });
      let timer = setInterval(()=>advance(1),6000);
      function resetAuto(){ clearInterval(timer); timer = setInterval(()=>advance(1),6000); }
      show(0);

      // Badge tooltips
      const badges = document.querySelectorAll('.badge');
      const tooltip = document.getElementById('tooltip');
      badges.forEach(b=>{
        b.addEventListener('mouseenter', e=>{
          tooltip.textContent = b.getAttribute('data-tooltip') || '';
          tooltip.style.opacity = '1'; tooltip.style.left = (e.pageX+10)+'px'; tooltip.style.top = (e.pageY-30)+'px'; tooltip.setAttribute('aria-hidden','false');
        });
        b.addEventListener('mouseleave', ()=>{ tooltip.style.opacity='0'; tooltip.setAttribute('aria-hidden','true'); });
        b.addEventListener('focus', e=>{ tooltip.textContent = b.getAttribute('data-tooltip') || ''; tooltip.style.opacity='1'; tooltip.style.left = (e.pageX+10)+'px'; tooltip.style.top = (e.pageY-30)+'px'; tooltip.setAttribute('aria-hidden','false'); });
        b.addEventListener('blur', ()=>{ tooltip.style.opacity='0'; tooltip.setAttribute('aria-hidden','true'); });
      });

    })();
  </script>
</body>
</html>"} 
{"path":"specialties.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Focus Areas — {{BUSINESS_NAME}}</title>
  <style>
    :root{--primary:#8b5cf6;--accent:#06b6d4;--bg:#071025;--card:#07151f;--muted:#9fb0c4}
    body{margin:0;font-family:system-ui,-apple-system,"Segoe UI",Roboto,Arial;background:radial-gradient(circle at 10% 10%, rgba(139,92,246,0.07), transparent 20%),var(--bg);color:#eaf5ff}
    header{display:flex;justify-content:space-between;align-items:center;padding:16px 22px;background:linear-gradient(90deg,rgba(255,255,255,0.02),transparent)}
    nav a{margin:0 10px;color:#dbeeff;text-decoration:none;font-weight:600}
    main{max-width:980px;margin:28px auto;padding:18px}
    .hero{padding:18px;border-radius:12px;background:linear-gradient(0deg,rgba(255,255,255,0.02),transparent)}
    h1{margin:0 0 8px 0}
    .grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px;margin-top:16px}
    .card{background:linear-gradient(180deg,rgba(255,255,255,0.01),transparent);padding:14px;border-radius:10px}
    .card h4{margin:0 0 6px 0}
    .note{color:var(--muted);font-size:14px}
    .proof{margin-top:16px;padding:12px;border-radius:10px;background:linear-gradient(90deg,rgba(255,255,255,0.01),transparent)}
    .cta{margin-top:18px}
    .btn{background:var(--primary);padding:10px 12px;border-radius:8px;color:white;text-decoration:none;font-weight:700}
    .secondary{background:transparent;border:1px solid rgba(255,255,255,0.04);color:#dbeeff;padding:9px 10px;border-radius:8px}
    footer{margin-top:24px;padding:18px;color:var(--muted);text-align:center}
    @media(max-width:760px){.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div style="font-weight:700">{{BUSINESS_NAME}}</div>
    <nav aria-label="Main nav">
      <a href="index.html">Start</a>
      <a href="about.html">Why work with me</a>
      <a href="specialties.html">Focus Areas</a>
      <a href="approach.html">Method</a>
      <a href="book.html">Schedule</a>
    </nav>
  </header>

  <main>
    <section class="hero">
      <h1>Areas I regularly work with</h1>
      <p class="note">Below are common themes that come up in sessions. If your experience isn’t listed, reach out — we’ll discuss whether this is a fit.</p>
    </section>

    <section class="grid" aria-label="focus areas">
      <div class="card">
        <h4>Life transitions</h4>
        <p class="note">When roles change — relationship shifts, parenting transitions, or career moves — we clarify priorities and make actionable plans for the next steps.</p>
      </div>
      <div class="card">
        <h4>Stress and burnout</h4>
        <p class="note">Practical strategies to reduce overwhelm, set boundaries, and design routines that support sustainable energy at work and at home.</p>
      </div>
      <div class="card">
        <h4>Decision work</h4>
        <p class="note">Structured sessions to weigh options, pilot small experiments, and reduce paralysis from uncertainty.</p>
      </div>
      <div class="card">
        <h4>Anxiety that interferes</h4>
        <p class="note">Skills-driven approaches to manage physical and cognitive symptoms so you can take practical steps without being derailed.</p>
      </div>
      <div class="card">
        <h4>Relationship patterns</h4>
        <p class="note">Explore habitual responses, communication shifts, and small experiments that change how connection feels day-to-day.</p>
      </div>
      <div class="card">
        <h4>Transitions to parenthood</h4>
        <p class="note">Support for individuals navigating the practical and emotional shifts when becoming a parent or changing caregiving roles.</p>
      </div>
    </section>

    <section class="proof" aria-labelledby="spec-proof">
      <h3 id="spec-proof">Proof Gallery</h3>
      <div id="spec-test" style="min-height:70px;margin-top:10px">"Sessions helped me try one small change that actually stuck." — K.</div>
      <div style="display:flex;justify-content:space-between;align-items:center;margin-top:10px">
        <div style="display:flex;gap:10px" id="spec-badges">
          <div class="badge" style="background:rgba(255,255,255,0.02);padding:8px;border-radius:8px" data-tooltip="Confidential and ethically bound practice">Ethics</div>
          <div class="badge" style="background:rgba(255,255,255,0.02);padding:8px;border-radius:8px" data-tooltip="Focused, single-day intensive option">Intensives</div>
        </div>
        <div>
          <button class="secondary" id="spec-prev">Prev</button>
          <button class="btn" id="spec-next">Next</button>
        </div>
      </div>
    </section>

    <section style="margin-top:18px;padding:16px;border-radius:10px;background:linear-gradient(180deg,rgba(255,255,255,0.01),transparent)">
      <h3 style="margin-top:0">How I frame offerings</h3>
      <p class="note">I offer a mix of single-session clarity work, focused multi-session packages, and a VIP day model for concentrated planning. Pricing and details are listed on the Investment page; this page helps you see which option might match your needs.</p>
      <div style="display:flex;gap:10px;margin-top:12px">
        <div style="flex:1;min-width:160px;background:rgba(255,255,255,0.02);padding:12px;border-radius:8px">
          <strong>Snapshot Session</strong>
          <p class="note">A 50-minute session to identify the immediate next step and try a short experiment between meetings.</p>
        </div>
        <div style="flex:1;min-width:160px;background:rgba(255,255,255,0.02);padding:12px;border-radius:8px">
          <strong>Focus Package</strong>
          <p class="note">Three to five sessions designed to move a particular concern forward with focused tools and review points.</p>
        </div>
        <div style="flex:1;min-width:160px;background:rgba(255,255,255,0.02);padding:12px;border-radius:8px">
          <strong>Clarity Day</strong>
          <p class="note">A concentrated day for mapping decisions, rehearsing difficult conversations, and making an implementable plan.</p>
        </div>
      </div>
    </section>

    <section class="cta" aria-label="next steps">
      <p class="note">If any of these areas feel relevant, we can begin with a short consult to determine a plan that fits your schedule and goals.</p>
      <a class="btn" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      <a class="secondary" href="contact.html" style="margin-left:8px">Ask a question — {{EMAIL}}</a>
    </section>

  </main>
  <footer>
    <div>{{BUSINESS_NAME}} • {{CITY}}, {{STATE}} • <a href="mailto:{{EMAIL}}" style="color:inherit">{{EMAIL}}</a></div>
  </footer>

  <div id="spec-tooltip" style="position:absolute;opacity:0;pointer-events:none;background:#07131b;color:#dbeeff;padding:8px;border-radius:6px;border:1px solid rgba(255,255,255,0.03)"></div>

  <script>
    (function(){
      const items = [
        '"Sessions helped me try one small change that actually stuck." — K.',
        '"Clear, practical guidance without pressure." — S.',
        '"The VIP day gave me a plan to use immediately at work." — T.'
      ];
      let index=0; const el=document.getElementById('spec-test');
      function show(i){ el.textContent=items[i]; }
      document.getElementById('spec-next').addEventListener('click', ()=>{ index=(index+1)%items.length; show(index); reset(); });
      document.getElementById('spec-prev').addEventListener('click', ()=>{ index=(index-1+items.length)%items.length; show(index); reset(); });
      let aut = setInterval(()=>{ index=(index+1)%items.length; show(index); },6000);
      function reset(){ clearInterval(aut); aut=setInterval(()=>{ index=(index+1)%items.length; show(index); },6000); }
      show(0);

      // badges tooltip
      const tip = document.getElementById('spec-tooltip');
      document.querySelectorAll('[data-tooltip]').forEach(b=>{
        b.addEventListener('mouseenter', e=>{ tip.textContent=b.getAttribute('data-tooltip'); tip.style.left=(e.pageX+10)+'px'; tip.style.top=(e.pageY-28)+'px'; tip.style.opacity=1; });
        b.addEventListener('mouseleave', ()=>{ tip.style.opacity=0; });
      });
    })();
  </script>
</body>
</html>"} 
{"path":"approach.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Method — {{BUSINESS_NAME}}</title>
  <style>
    :root{--accent:#ef4444;--bg:#061226;--panel:#071a2b;--muted:#9cb0c6}
    body{margin:0;font-family:Inter,system-ui,-apple-system,"Segoe UI",Roboto,Arial;background:linear-gradient(180deg,#041023,var(--bg));color:#e9f3ff}
    header{display:flex;justify-content:space-between;align-items:center;padding:16px 20px}
    nav a{margin:0 9px;color:#dbeeff;text-decoration:none}
    main{max-width:900px;margin:28px auto;padding:18px}
    .lead{padding:18px;background:linear-gradient(90deg,rgba(255,255,255,0.02),transparent);border-radius:10px}
    .steps{display:flex;flex-direction:column;gap:12px;margin-top:14px}
    .step{display:flex;gap:12px;background:var(--panel);padding:12px;border-radius:8px}
    .step h4{margin:0;color:#fff}
    .meter{height:8px;background:rgba(255,255,255,0.03);border-radius:6px;margin-top:8px}
    .meter-inner{height:8px;border-radius:6px;background:linear-gradient(90deg,var(--accent),#f97316)}
    .conf{margin-top:18px;padding:12px;border-radius:10px;background:linear-gradient(180deg,rgba(255,255,255,0.01),transparent)}
    .btn{background:var(--accent);padding:10px 12px;border-radius:8px;color:white;text-decoration:none}
    .proof{margin-top:14px;padding:12px;border-radius:10px;background:linear-gradient(90deg,rgba(255,255,255,0.01),transparent)}
    footer{margin-top:20px;padding:18px;text-align:center;color:var(--muted)}
    @media(max-width:720px){.step{flex-direction:column}}
  </style>
</head>
<body>
  <header>
    <div style="font-weight:700">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="index.html">Start</a>
      <a href="about.html">Why work with me</a>
      <a href="specialties.html">Focus Areas</a>
      <a href="approach.html">Method</a>
      <a href="book.html">Schedule</a>
    </nav>
  </header>

  <main>
    <section class="lead">
      <h1 style="margin:0">A pragmatic, clinician-led approach</h1>
