  <script>
    (function(){
      // proof rotation (shared behavior)
      const items=[
        '"Concrete steps felt doable and relevant to my life." — A.',
        '"We practiced a conversation and I didn’t freeze — that was huge." — D.',
        '"Short, structured sessions made it easy to keep momentum." — J.'
      ];
      let i=0; const el=document.getElementById('appr-test');
      function show(n){ el.textContent = items[n]; }
      show(0); setInterval(()=>{ i=(i+1)%items.length; show(i); },6000);

      // contact button
      document.getElementById('appr-contact').addEventListener('click', ()=>{ location.href='{{PRIMARY_CTA_URL}}'; });

      // badge tooltip
      const tip=document.getElementById('appr-tooltip');
      document.querySelectorAll('[data-tooltip]').forEach(b=>{
        b.addEventListener('mouseenter', e=>{ tip.textContent=b.getAttribute('data-tooltip'); tip.style.left=(e.pageX+10)+'px'; tip.style.top=(e.pageY-28)+'px'; tip.style.opacity=1; });
        b.addEventListener('mouseleave', ()=>{ tip.style.opacity=0; });
      });

    })();
